      <div class="infinite-wall-toolbar"><div><p class="eyebrow">Active wall</p><h3>${esc(wall.name)}</h3><span>${esc(wall.description||'Infinite investigation canvas')}</span><strong>${state.dossiers.length} dossiers · ${appearances.length} appearances · ${activeRegions().length} regions</strong></div><div class="button-row desktop-wall-actions"><button class="primary-button" data-new-dossier>Add Dossier</button><button class="secondary-button" data-new-region>Add Region</button><button class="secondary-button" data-action="create-link">Link Dossiers</button><button class="secondary-button" data-card-view>Card View</button><button class="secondary-button" data-connections-manager>Connections</button><button type="button" class="zoom-hold-button" data-zoom="out" aria-label="Zoom out">Zoom −</button><output id="wallZoom">${Math.round(viewport.zoom*100)}%</output><button type="button" class="zoom-hold-button" data-zoom="in" aria-label="Zoom in">Zoom +</button><button type="button" data-fit-all>Fit Wall</button><button type="button" data-reset-view>Reset View</button></div></div>
