  function openDossierEditor(id='',appearanceId='') {if(globalThis.DossierExperience?.openEditor)return globalThis.DossierExperience.openEditor(id);const d=id?dossierById(id):null;modal(`<div class="dossier-editor"><p class="eyebrow">${d?'Edit canonical dossier':'New canonical dossier'}</p><h2 id="formModalTitle">${esc(d?.title||'Build a dossier')}</h2><div class="form-grid"><label class="form-group"><span class="field-label">Category</span><input id="dCategory" class="text-input" value="${esc(d?.category||'Evidence')}"></label><label class="form-group"><span class="field-label">Title</span><input id="dTitle" class="text-input" value="${esc(d?.title||'')}"></label><label class="form-group full"><span class="field-label">Summary</span><textarea id="dSummary" class="text-area">${esc(d?.summary||'')}</textarea></label><label class="form-group"><span class="field-label">Image URL</span><input id="dImage" class="text-input" value="${esc(d?.image||'')}"></label><label class="form-group"><span class="field-label">Tags, comma separated</span><input id="dTags" class="text-input" value="${esc((d?.tags||[]).join(', '))}"></label><label class="form-group"><span class="field-label">Series</span><input id="dSeries" class="text-input" list="seriesChoices" value="${esc(seriesName(d?.seriesId))}" placeholder="No series"><datalist id="seriesChoices">${state.series.map(item=>`<option value="${esc(item.name)}"></option>`).join('')}</datalist></label><label class="form-group"><span class="field-label">Legacy source book</span><select id="dBook"><option value="">No book</option>${bookOptions(d?.sourceBookId||'')}</select></label><label class="form-group"><span class="field-label">Spoiler threshold</span><input id="dSpoiler" class="text-input" value="${esc(d?.spoilerThreshold||'')}"></label></div><section class="editor-section"><header><h3>Books</h3><small>Select zero or more books; outside-series choices are preserved.</small></header>${dossierBooksEditor(d||{})}</section><section class="editor-section"><header><h3>Appearances and Regions</h3><small>One home per wall; one reference per region.</small></header><div id="appearanceRegionEditor">${appearancesEditorHtml(d)}</div></section><section class="editor-section"><header><h3>Custom Fields</h3><button id="addDossierField" type="button">＋ Add Field</button></header><div id="dossierFields">${(d?.fields||[]).map(fieldEditorRow).join('')}</div></section><section class="editor-section"><header><h3>Custom Sections</h3><button id="addDossierSection" type="button">＋ Add Section</button></header><div id="dossierSections">${(d?.sections||[]).map(sectionRow).join('')}</div></section><section class="editor-section"><h3>Tile Front</h3><div class="form-grid"><label>Mode<select id="dMode">${['compact','standard','expanded'].map(x=>`<option ${d?.tileSettings?.mode===x?'selected':''}>${x}</option>`).join('')}</select></label>${[['Summary','showSummary'],['Image','showImage'],['Counts','showCounts'],['Tags','showTags'],['Category','showCategory'],['Series','showSeries'],['Books','showBooks']].map(([label,key])=>`<label class="form-check"><input type="checkbox" id="${key}" ${(d?.tileSettings?.[key]??defaultTileSettings()[key])?'checked':''}>${label}</label>`).join('')}<label>Books style<select id="bookStyle">${['chips','count','first','full'].map(style=>`<option ${d?.tileSettings?.bookStyle===style?'selected':''}>${style}</option>`).join('')}</select></label></div></section><div class="button-row"><button class="primary-button" id="saveDossier">Save Dossier</button>${d?'<button class="secondary-button" id="deleteDossier">Delete Canonical Dossier</button>':''}</div></div>`);document.getElementById('formModal').classList.add('dossier-drawer');
    organizeDossierEditor(d);
    const fields=document.getElementById('dossierFields'),sections=document.getElementById('dossierSections'); fields.insertAdjacentHTML ||= function(){};
    const refreshBookVisibility=()=>{const query=document.getElementById('dBookSearch').value.toLowerCase(),series=state.series.find(item=>item.name.toLowerCase()===v('dSeries').toLowerCase())?.id||'',chips=document.getElementById('selectedBookChips');document.querySelectorAll('.book-choice').forEach(label=>{label.hidden=!!query&&!label.dataset.bookSearch.includes(query);label.classList.toggle('outside-series',!!series&&label.dataset.bookSeries!==series);});chips.innerHTML=[...document.querySelectorAll('.book-choice input:checked')].map(input=>`<button type="button" data-remove-book="${input.value}">${esc(state.books.find(book=>book.id===input.value)?.title||'Book')} ×</button>`).join('');};
    document.getElementById('dBookSearch').oninput=refreshBookVisibility;document.getElementById('dSeries').onchange=refreshBookVisibility;document.getElementById('dossierBookChoices').onchange=refreshBookVisibility;document.getElementById('selectedBookChips').onclick=event=>{const button=event.target.closest('[data-remove-book]');if(button){document.querySelector(`.book-choice input[value="${CSS.escape(button.dataset.removeBook)}"]`).checked=false;refreshBookVisibility();}};refreshBookVisibility();document.getElementById('selectSeriesBooks').onclick=()=>{const series=state.series.find(item=>item.name.toLowerCase()===v('dSeries').toLowerCase())?.id;document.querySelectorAll('.book-choice').forEach(label=>{if(series&&label.dataset.bookSeries===series)label.querySelector('input').checked=true;});};document.getElementById('clearDossierBooks').onclick=()=>{document.querySelectorAll('.book-choice input').forEach(input=>input.checked=false);refreshBookVisibility();};
    const appearanceEditor=document.getElementById('appearanceRegionEditor');if(d)appearanceEditor.onclick=e=>{const wallRow=e.target.closest('[data-appearance-wall]');if(!wallRow)return;const wallId=wallRow.dataset.appearanceWall;if(e.target.closest('[data-apply-home]')){moveHomeRegion(d.id,wallId,wallRow.querySelector('.home-region').value,wallRow.querySelector('.leave-reference').checked);saveState();openDossierEditor(d.id);return;}if(e.target.closest('[data-add-editor-reference]')){addRegionReference(d.id,wallId,wallRow.querySelector('.reference-region').value);normalizeSeriesAndIntegrity();saveState();openDossierEditor(d.id);return;}const remove=e.target.closest('[data-remove-editor-reference]'),promote=e.target.closest('[data-promote-editor-reference]'),jump=e.target.closest('[data-jump-editor-appearance]');if(remove){state.wallAppearances=state.wallAppearances.filter(item=>item.id!==remove.dataset.removeEditorReference);saveState();openDossierEditor(d.id);}if(promote){const ref=appearanceById(promote.dataset.promoteEditorReference);moveHomeRegion(d.id,ref.wallId,ref.regionId,false);saveState();openDossierEditor(d.id);}if(jump)jumpToAppearance(jump.dataset.jumpEditorAppearance);};
    document.getElementById('addDossierField').onclick=()=>{fields.insertAdjacentHTML('beforeend',fieldEditorRow());};document.getElementById('addDossierSection').onclick=()=>sections.insertAdjacentHTML('beforeend',sectionRow());bindReorder(fields,'.dossier-field-editor','data-move-field','data-remove-field');bindReorder(sections,'.dossier-section-editor','data-move-section','data-remove-section');
    fields.onchange=e=>{if(!e.target.classList.contains('field-type'))return;const row=e.target.closest('.dossier-field-editor'),old=row.querySelector('.field-value'),linked=['linked','multi-linked'].includes(e.target.value);if(linked)old.outerHTML=linkedSelect(e.target.value==='multi-linked',[]);else old.outerHTML='<textarea class="text-area field-value" placeholder="Value"></textarea>';};
    document.getElementById('saveDossier').onclick=()=>{const title=v('dTitle');if(!title)return showToast('A dossier needs a title.');const now=Date.now(),seriesId=state.series.find(item=>item.name.toLowerCase()===v('dSeries').toLowerCase())?.id||'',bookIds=[...document.querySelectorAll('.book-choice input:checked')].map(input=>input.value),data={category:v('dCategory')||'Custom',title,summary:v('dSummary'),image:v('dImage'),tags:csv(v('dTags')),seriesId,bookIds,sourceBookId:v('dBook'),spoilerThreshold:v('dSpoiler'),fields:[...fields.querySelectorAll('.dossier-field-editor')].map(row=>{const input=row.querySelector('.field-value'),multiple=input.multiple;return{id:row.dataset.fieldId,name:row.querySelector('.field-name').value.trim(),type:row.querySelector('.field-type').value,value:multiple?[...input.selectedOptions].map(o=>o.value).filter(Boolean):input.value,showOnFront:row.querySelector('.field-front').checked,frontStyle:row.querySelector('.field-style').value};}).filter(f=>f.name),sections:[...sections.querySelectorAll('.dossier-section-editor')].map(row=>({id:row.dataset.sectionId,title:row.querySelector('.section-name').value.trim(),value:row.querySelector('.section-value').value.trim()})).filter(s=>s.title||s.value),tileSettings:{mode:v('dMode'),showSummary:document.getElementById('showSummary').checked,showImage:document.getElementById('showImage').checked,showCounts:document.getElementById('showCounts').checked,showTags:document.getElementById('showTags').checked,showCategory:document.getElementById('showCategory').checked,showSeries:document.getElementById('showSeries').checked,showBooks:document.getElementById('showBooks').checked,bookStyle:v('bookStyle')},updatedAt:now};if(d)Object.assign(d,data);else{const dossier={id:uid(),...data,createdAt:now,sourceType:'custom'};state.dossiers.push(dossier);state.wallAppearances.push({id:uid(),dossierId:dossier.id,wallId:state.activeWallId,regionId:'',appearanceType:'home',x:80,y:100,width:300,height:null,displayMode:data.tileSettings.mode,zIndex:10,locked:false});}normalizeSeriesAndIntegrity();runAutomaticAssignments();saveState();closeDossierModal();renderWall();};
    if(d)document.getElementById('deleteDossier').onclick=()=>{if(!confirm(`Delete ${d.title} and every appearance and link?`))return;state.dossiers=state.dossiers.filter(x=>x.id!==d.id);state.wallAppearances=state.wallAppearances.filter(x=>x.dossierId!==d.id);state.dossierLinks=state.dossierLinks.filter(x=>x.fromDossierId!==d.id&&x.toDossierId!==d.id);state.dossiers.forEach(x=>(x.fields||[]).forEach(f=>{if(['linked','multi-linked'].includes(f.type)){const values=Array.isArray(f.value)?f.value:[f.value];f.value=(f.type==='linked'?values.filter(y=>y!==d.id)[0]||'':values.filter(y=>y!==d.id));}}));saveState();closeDossierModal();renderWall();};
  }
  function closeDossierModal(){document.getElementById('formModal').classList.remove('dossier-drawer');closeModal();}

  function openDossier(id,appearanceId='') {if(globalThis.DossierExperience?.openProfile)return globalThis.DossierExperience.openProfile(id,appearanceId);const d=dossierById(id);if(!d)return;const links=dossierLinks(id),appearances=state.wallAppearances.filter(a=>a.dossierId===id);modal(`<div class="dossier-detail"><p class="eyebrow">${esc(d.category)}</p><h2 id="formModalTitle">${esc(d.title)}</h2>${d.image?`<img class="dossier-hero" src="${esc(d.image)}" alt="">`:''}<p class="dossier-detail-summary">${esc(d.summary||'No summary recorded.')}</p>${d.tags?.length?`<div class="dossier-tags">${d.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}<div class="dossier-detail-grid"><section><h3>Fields</h3>${(d.fields||[]).map(f=>`<div class="detail-field"><small>${esc(f.name)}</small><strong>${esc(fieldValue(f))}</strong></div>`).join('')||'<p>No custom fields.</p>'}</section><section><h3>Sections</h3>${(d.sections||[]).map(s=>`<article><h4>${esc(s.title)}</h4><p>${esc(s.value)}</p></article>`).join('')||'<p>No custom sections.</p>'}</section><section><h3>Connections</h3>${links.map(l=>{const other=dossierById(l.fromDossierId===id?l.toDossierId:l.fromDossierId);return `<button data-jump-dossier="${other?.id||''}">${esc(l.type)} · ${esc(other?.title||'Missing')}</button><p>${esc(l.reason||'')}</p>`;}).join('')||'<p>No links.</p>'}</section><section><h3>Appearances</h3>${appearances.map(a=>{const w=state.walls.find(x=>x.id===a.wallId),r=state.wallRegions.find(x=>x.id===a.regionId);return `<button data-jump-appearance="${a.id}">${a.appearanceType==='reference'?'Reference':'Home'} · ${esc(w?.name||'')} ${r?`› ${esc(r.name)}`:''}</button>`;}).join('')}</section></div><p class="field-help">Source: ${esc(state.books.find(b=>b.id===d.sourceBookId)?.title||'None')} · Spoilers: ${esc(d.spoilerThreshold||'Not set')} · Updated ${new Date(d.updatedAt||d.createdAt).toLocaleString()}</p><div class="button-row"><button class="primary-button" id="editDossier">Edit dossier</button><button class="secondary-button" id="addReference">Add Another Appearance</button>${appearanceId&&appearanceById(appearanceId)?.appearanceType==='reference'?'<button class="secondary-button" id="deleteReference">Remove this reference</button>':''}</div></div>`);document.getElementById('formModal').classList.add('dossier-drawer');document.getElementById('editDossier').onclick=()=>openDossierEditor(id,appearanceId);document.getElementById('addReference').onclick=()=>{state.wallAppearances.push({id:uid(),dossierId:id,wallId:state.activeWallId,regionId:'',appearanceType:'reference',intentionalDuplicate:true,x:120,y:130,width:240,height:null,displayMode:'compact',zIndex:10,locked:false});saveState();closeDossierModal();renderWall();};if(document.getElementById('deleteReference'))document.getElementById('deleteReference').onclick=()=>{state.wallAppearances=state.wallAppearances.filter(a=>a.id!==appearanceId);saveState();closeDossierModal();renderWall();};document.querySelectorAll('[data-jump-appearance]').forEach(b=>b.onclick=()=>jumpToAppearance(b.dataset.jumpAppearance));document.querySelectorAll('[data-jump-dossier]').forEach(b=>b.onclick=()=>openDossier(b.dataset.jumpDossier));}
  function jumpToAppearance(id){const a=appearanceById(id);if(!a)return;state.activeWallId=a.wallId;saveState();closeDossierModal();renderWall();requestAnimationFrame(()=>focusAppearance(id));}

  function openDuplicateReview(){const groups=duplicateAppearanceGroups(activeAppearances());modal(`<div class="duplicate-review"><p class="eyebrow">Appearance audit</p><h2 id="formModalTitle">Review duplicate appearances</h2><p>These are multiple visual placements of the same dossier on this wall. Nothing has been removed automatically.</p>${groups.map(group=>{const dossier=dossierById(group.dossierId);return`<article data-duplicate-group="${esc(group.key)}"><header><div><strong>${esc(dossier?.title||'Missing dossier')}</strong><small>${group.items.length} appearances · ${group.intentional?'Marked intentional':'Needs review'}</small></div><button type="button" data-keep-duplicate-group="${esc(group.key)}">Keep All</button></header>${group.items.map((item,index)=>{const region=state.wallRegions.find(value=>value.id===item.regionId);return`<label><input type="checkbox" value="${item.id}" ${index?'':'disabled'}><span>${index?'Additional':'Primary review item'} · ${esc(region?.name||'Loose on wall')} · ${Math.round(finite(appearanceWorld(item).x))}, ${Math.round(finite(appearanceWorld(item).y))}</span></label>`;}).join('')}<button type="button" class="secondary-button" data-remove-reviewed="${esc(group.key)}">Remove selected appearances</button></article>`;}).join('')||'<p>No same-wall duplicate appearances were found.</p>'}<div class="experience-footer"><button type="button" class="primary-button" id="doneDuplicateReview">Done</button></div></div>`);document.querySelector('.duplicate-review').onclick=event=>{const keep=event.target.closest('[data-keep-duplicate-group]'),remove=event.target.closest('[data-remove-reviewed]');if(keep){const group=duplicateAppearanceGroups(activeAppearances()).find(item=>item.key===keep.dataset.keepDuplicateGroup);group?.items.forEach(item=>item.intentionalDuplicate=true);saveState();openDuplicateReview();}if(remove){const article=remove.closest('[data-duplicate-group]'),ids=[...article.querySelectorAll('input:checked:not(:disabled)')].map(input=>input.value);if(!ids.length)return showToast('Select an additional appearance to remove.');if(!confirm(`Remove ${ids.length} selected appearance${ids.length===1?'':'s'}? The dossier and other walls will not be changed.`))return;state.wallAppearances=state.wallAppearances.filter(item=>!ids.includes(item.id));saveState();openDuplicateReview();}};document.getElementById('doneDuplicateReview').onclick=()=>{closeModal();renderWall();};}

  function openCardActions(appearanceId){const appearance=appearanceById(appearanceId),dossier=appearance&&dossierById(appearance.dossierId);if(!appearance||!dossier)return;modal(`<div class="card-actions-dialog"><p class="eyebrow">Dossier card actions</p><h2 id="formModalTitle">${esc(dossier.title)}</h2><p>${esc(dossier.category)} · ${appearance.appearanceType==='home'?'Primary placement':'Additional placement'}</p><div class="mobile-action-grid"><button type="button" class="primary-button" id="actionOpenDossier">Open dossier</button><button type="button" id="actionEditDossier">Edit dossier</button><button type="button" id="actionConnections">Connections (${dossierLinks(dossier.id).length})</button><button type="button" id="actionLinkDossier">Link to another dossier</button><button type="button" id="actionSelectCard">${selectedAppearanceIds.has(appearanceId)?'Deselect card':'Select card'}</button><button type="button" id="actionCardView">Card display</button></div><fieldset><legend>Card size</legend><div class="segmented mobile-size-options">${[['small','Small'],['medium','Medium'],['large','Large']].map(([size,label])=>`<button type="button" data-quick-size="${size}">${label}</button>`).join('')}</div><p class="field-help">For custom sizing, select the card and use its large resize handle. Arrow keys resize in 10-pixel steps.</p></fieldset><div class="experience-footer"><button type="button" class="secondary-button" id="actionRemovePlacement">Remove this placement</button><button type="button" class="danger-button" id="actionDeleteEverywhere">Delete dossier everywhere</button><button type="button" class="secondary-button" id="actionCancel">Cancel</button></div></div>`);document.getElementById('actionOpenDossier').onclick=()=>openDossier(dossier.id,appearanceId);document.getElementById('actionEditDossier').onclick=()=>{if(globalThis.DossierExperience?.openEditor)globalThis.DossierExperience.openEditor(dossier.id);else openDossierEditor(dossier.id);};document.getElementById('actionConnections').onclick=()=>openConnectionsManager(dossier.id);document.getElementById('actionLinkDossier').onclick=()=>{closeModal();startQuickLink(appearanceId);};document.getElementById('actionSelectCard').onclick=()=>{selectedAppearanceIds.has(appearanceId)?selectedAppearanceIds.delete(appearanceId):selectedAppearanceIds.add(appearanceId);closeModal();renderWall();};document.getElementById('actionCardView').onclick=()=>{selectedAppearanceIds.add(appearanceId);globalThis.DossierExperience?.openCardView?.();};document.querySelectorAll('[data-quick-size]').forEach(button=>button.onclick=()=>{const size=button.dataset.quickSize,width={small:240,medium:310,large:430}[size],height={small:150,medium:210,large:300}[size];appearance.width=width;appearance.height=height;appearance.manualSize=true;saveState();closeModal();renderWall();});document.getElementById('actionRemovePlacement').onclick=()=>{if(appearance.appearanceType==='home'&&!confirm('Remove the primary placement from this wall? The dossier record will remain available elsewhere.'))return;state.wallAppearances=state.wallAppearances.filter(item=>item.id!==appearanceId);saveState();closeModal();renderWall();};document.getElementById('actionDeleteEverywhere').onclick=()=>{if(!confirm(`Delete ${dossier.title}, every wall placement, and every relationship? This cannot be undone.`))return;state.dossiers=state.dossiers.filter(item=>item.id!==dossier.id);state.wallAppearances=state.wallAppearances.filter(item=>item.dossierId!==dossier.id);state.dossierLinks=state.dossierLinks.filter(link=>link.fromDossierId!==dossier.id&&link.toDossierId!==dossier.id);saveState();closeModal();renderWall();};document.getElementById('actionCancel').onclick=()=>closeModal();}
  function openConnectionsManager(dossierId=''){const links=state.dossierLinks.filter(link=>!dossierId||link.fromDossierId===dossierId||link.toDossierId===dossierId);modal(`<div class="connections-manager"><p class="eyebrow">Relationship access</p><h2 id="formModalTitle">Connections${dossierId?` for ${esc(dossierById(dossierId)?.title||'dossier')}`:''}</h2><p>Use this list when connection lines are crowded or too small to select.</p><div class="connection-access-list">${links.map(link=>{const from=dossierById(link.fromDossierId),to=dossierById(link.toDossierId);return`<article><div><strong>${esc(from?.title||'Missing dossier')} · ${esc(link.type)} · ${esc(to?.title||'Missing dossier')}</strong><p>${esc(link.reason||'No notes recorded.')}</p></div><button type="button" data-edit-relationship="${link.id}">Inspect or edit</button></article>`;}).join('')||'<p>No relationships are available on this wall.</p>'}</div><div class="experience-footer"><button type="button" class="primary-button" id="startConnectionFromList">Link Dossiers</button><button type="button" class="secondary-button" id="closeConnectionsManager">Close</button></div></div>`);document.querySelector('.connection-access-list').onclick=event=>{const button=event.target.closest('[data-edit-relationship]');if(button)openRelationshipEditor(button.dataset.editRelationship);};document.getElementById('startConnectionFromList').onclick=()=>{closeModal();startQuickLink();};document.getElementById('closeConnectionsManager').onclick=()=>closeModal();}
  function openRelationshipEditor(linkId){const link=state.dossierLinks.find(item=>item.id===linkId);if(!link)return;const from=dossierById(link.fromDossierId),to=dossierById(link.toDossierId);modal(`<div class="quick-link-dialog"><p class="eyebrow">Relationship details</p><h2 id="formModalTitle">Inspect Connection</h2><div class="quick-link-sentence"><strong>${esc(from?.title||'Missing dossier')}</strong><input id="relationshipType" value="${esc(link.type)}" aria-label="Relationship phrase"><strong>${esc(to?.title||'Missing dossier')}</strong></div><label>Reason or notes<textarea id="relationshipReason" rows="4">${esc(link.reason||'')}</textarea></label><details class="advanced-options" open><summary>Advanced details</summary><div class="friendly-grid"><label>Source book<select id="relationshipBook"><option value="">None</option>${bookOptions(link.sourceBookId)}</select></label><label>Chapter<input id="relationshipChapter" value="${esc(link.chapter||'')}"></label><label>Confidence<input id="relationshipConfidence" type="number" min="0" max="100" value="${esc(link.confidence||'')}"></label><label>Spoiler level<input id="relationshipSpoiler" value="${esc(link.spoilerThreshold||'')}"></label></div></details><div class="experience-footer"><button type="button" class="primary-button" id="saveRelationshipEdit">Save relationship</button><button type="button" class="secondary-button" id="cancelRelationshipEdit">Cancel</button><button type="button" class="danger-button" id="deleteRelationship">Delete relationship</button></div></div>`);document.getElementById('saveRelationshipEdit').onclick=()=>{Object.assign(link,{type:v('relationshipType')||'is connected to',reason:v('relationshipReason'),sourceBookId:v('relationshipBook'),chapter:v('relationshipChapter'),confidence:v('relationshipConfidence'),spoilerThreshold:v('relationshipSpoiler')});saveState();closeModal();renderWall();};document.getElementById('cancelRelationshipEdit').onclick=()=>closeModal();document.getElementById('deleteRelationship').onclick=()=>{if(!confirm('Delete this relationship?'))return;state.dossierLinks=state.dossierLinks.filter(item=>item.id!==link.id);saveState();closeModal();renderWall();};}

  function ruleRow(rule={}){return `<div class="rule-row" data-rule-id="${rule.id||uid()}"><input class="rule-key" value="${esc(rule.key||'category')}" placeholder="category, seriesId, bookIds, field:Status"><select class="rule-operator">${['equals','notEquals','oneOf','contains','gt','lt','hasLinks','noLinks','booksAny','booksAll','multiBook','currentWallBook','currentWallSeries','none'].map(x=>`<option value="${x}" ${rule.operator===x?'selected':''}>${x}</option>`).join('')}</select><input class="rule-value" value="${esc(rule.value||'')}" placeholder="Match IDs or value"><button type="button" data-remove-rule>×</button></div>`;}
  function openRegionEditor(id=''){const r=id?state.wallRegions.find(x=>x.id===id):null;modal(`<p class="eyebrow">Canvas region</p><h2 id="formModalTitle">${r?'Edit Region':'Add Region'}</h2><div class="form-grid"><label>Name<input id="rName" class="text-input" value="${esc(r?.name||'New Region')}"></label><label>Color<input id="rColor" type="color" value="${esc(r?.color||'#856b9e')}"></label><label class="full">Description<textarea id="rDesc" class="text-area">${esc(r?.description||'')}</textarea></label><label>Layout<select id="rLayout">${LAYOUTS.map(x=>`<option ${r?.layoutMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Sort<select id="rSort">${SORTS.map(x=>`<option ${r?.sortMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Assignment<select id="rAssignment">${['manual','assisted','automatic'].map(x=>`<option ${r?.assignmentMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-check"><input id="rLocked" type="checkbox" ${r?.locked?'checked':''}>Locked</label><label class="form-check"><input id="rReferences" type="checkbox" ${r?.allowReferences!==false?'checked':''}>Allow references</label></div><section class="editor-section"><header><div><h3>Matching Rules</h3><small>All rules use AND logic. Use field:Field Name for custom fields.</small></div><button id="addRule" type="button">＋ Rule</button></header><div id="regionRules">${(r?.rules||[]).map(ruleRow).join('')}</div></section><div class="button-row"><button id="saveRegion" class="primary-button">Save Region</button><button id="cancelRegion" class="secondary-button">Cancel</button>${r?'<button id="forwardRegion">Bring Forward</button><button id="backRegion">Send Back</button><button id="deleteRegion" class="secondary-button">Delete Region</button>':''}</div>`);const rules=document.getElementById('regionRules');document.getElementById('cancelRegion').onclick=()=>closeModal();document.getElementById('addRule').onclick=()=>rules.insertAdjacentHTML('beforeend',ruleRow());rules.onclick=e=>{if(e.target.closest('[data-remove-rule]'))e.target.closest('.rule-row').remove();};document.getElementById('saveRegion').onclick=()=>{const data={name:v('rName')||'Region',description:v('rDesc'),color:v('rColor'),layoutMode:v('rLayout'),sortMode:v('rSort'),assignmentMode:v('rAssignment'),locked:document.getElementById('rLocked').checked,allowReferences:document.getElementById('rReferences').checked,rules:[...rules.querySelectorAll('.rule-row')].map(row=>({id:row.dataset.ruleId,key:row.querySelector('.rule-key').value.trim(),operator:row.querySelector('.rule-operator').value,value:row.querySelector('.rule-value').value.trim()}))};if(r)Object.assign(r,data);else state.wallRegions.push({id:uid(),wallId:state.activeWallId,...data,x:80,y:80,width:760,height:520,zIndex:1,collapsed:false});saveState();closeModal();renderWall();};if(r){document.getElementById('forwardRegion').onclick=()=>{r.zIndex=Math.max(...activeRegions().map(x=>x.zIndex||1))+1;saveState();closeModal();renderWall();};document.getElementById('backRegion').onclick=()=>{r.zIndex=Math.min(...activeRegions().map(x=>x.zIndex||1))-1;saveState();closeModal();renderWall();};document.getElementById('deleteRegion').onclick=()=>{if(!confirm('Delete this region? Dossiers will become unassigned.'))return;state.wallAppearances.filter(a=>a.regionId===r.id).forEach(a=>a.regionId='');state.wallRegions=state.wallRegions.filter(x=>x.id!==r.id);saveState();closeModal();renderWall();};}}
  function acceptSuggestions(id){const r=state.wallRegions.find(x=>x.id===id);matchingDossiers(r).forEach(d=>assignMatchingDossier(d,r));normalizeSeriesAndIntegrity();saveState();renderWall();}

  function startQuickLink(prefill=''){const dossierId=appearanceById(prefill)?.dossierId||dossierById(prefill)?.id||'';if(state.dossiers.length<2)return showToast('Add at least two dossiers first.');quickLink.active=true;quickLink.firstDossierId=dossierId;quickLink.secondDossierId='';selectedAppearanceIds.clear();renderWall();if(location.search.includes('debugActions=1'))console.debug('[wall-action] link mode started',dossierId);}
  function cancelQuickLink(){if(!quickLink.active)return;quickLink.active=false;quickLink.firstDossierId='';quickLink.secondDossierId='';renderWall();if(location.search.includes('debugActions=1'))console.debug('[wall-action] link mode canceled');}
  function chooseQuickLinkDossier(dossierId){if(!quickLink.firstDossierId){quickLink.firstDossierId=dossierId;renderWall();return;}if(quickLink.firstDossierId===dossierId)return showToast('Choose a different dossier.');const from=quickLink.firstDossierId;quickLink.active=false;quickLink.secondDossierId=dossierId;renderWall();requestAnimationFrame(()=>openQuickLinkDialog(from,dossierId));}
  function openQuickLinkDialog(fromId,toId){const from=dossierById(fromId),to=dossierById(toId);modal(`<div class="quick-link-dialog"><p class="eyebrow">Wall quick link</p><h2 id="formModalTitle">Link Dossiers</h2><div class="quick-link-sentence"><strong>${esc(from.title)}</strong><input id="quickLinkType" value="is connected to" aria-label="Relationship phrase"><strong>${esc(to.title)}</strong></div><label>Reason or notes<textarea id="quickLinkReason" rows="4"></textarea></label><details class="advanced-options"><summary>Advanced details</summary><div class="friendly-grid"><label>Source book<select id="quickLinkBook"><option value="">None</option>${bookOptions()}</select></label><label>Chapter<input id="quickLinkChapter"></label><label>Confidence<input id="quickLinkConfidence" type="number" min="0" max="100"></label><label>Spoiler level<input id="quickLinkSpoiler"></label></div></details><div class="experience-footer"><button type="button" class="primary-button" id="saveQuickLink">Save Connection</button><button type="button" class="secondary-button" id="cancelQuickLinkDialog">Cancel</button></div></div>`);document.getElementById('saveQuickLink').onclick=()=>{const type=v('quickLinkType')||'is connected to',duplicate=state.dossierLinks.some(link=>link.fromDossierId===fromId&&link.toDossierId===toId&&String(link.type).toLowerCase()===type.toLowerCase());if(duplicate&&!confirm('An identical connection already exists. Add another anyway?'))return;state.dossierLinks.push({id:uid(),fromDossierId:fromId,toDossierId:toId,type,reason:v('quickLinkReason'),sourceBookId:v('quickLinkBook'),chapter:v('quickLinkChapter'),confidence:v('quickLinkConfidence'),spoilerThreshold:v('quickLinkSpoiler'),createdAt:Date.now()});quickLink.firstDossierId='';quickLink.secondDossierId='';saveState();closeModal();renderWall();showToast('Dossiers linked.');if(location.search.includes('debugActions=1'))console.debug('[wall-action] link mode completed',fromId,toId,type);};document.getElementById('cancelQuickLinkDialog').onclick=()=>{quickLink.firstDossierId='';quickLink.secondDossierId='';closeModal();renderWall();};}
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileToolsState.open){event.preventDefault();closeMobileTools();return;}if(event.key==='Escape'&&quickLink.active){event.preventDefault();cancelQuickLink();return;}if(activeView!=='wall'||document.body.classList.contains('modal-open')||event.target.closest?.('input,textarea,select,[contenteditable=true]'))return;if(event.key==='+'||event.key==='='){event.preventDefault();zoomAt(1.2);}if(event.key==='-'){event.preventDefault();zoomAt(1/1.2);}if(event.key==='0'){event.preventDefault();resetView();}if(event.key.toLowerCase()==='f'){event.preventDefault();fitAll();}});
  let viewportResizeTimer;const handleViewportResize=()=>{clearTimeout(viewportResizeTimer);viewportResizeTimer=setTimeout(()=>{if(activeView==='wall'){applyTransform();redraw();}},120);};window.addEventListener('resize',handleViewportResize,{passive:true});window.addEventListener('orientationchange',()=>{resetGestureState(document.getElementById('infiniteCanvas'));handleViewportResize();},{passive:true});window.addEventListener('blur',()=>stopZoomHold(undefined,true));document.addEventListener('visibilitychange',()=>{if(document.hidden)stopZoomHold(undefined,true);});

  openWallCardForm = function(){openDossierEditor();};
  modal = function accessibleModal(html){resetGestureState(document.getElementById('infiniteCanvas'));if(!document.body.classList.contains('modal-open'))modalReturnFocus=document.activeElement;originalModal(html);const backdrop=document.getElementById('formModal'),dialog=backdrop.querySelector('.modal'),pathKey=document.getElementById('app').dataset.path;backdrop.classList.toggle('book-modal-backdrop',Boolean(backdrop.querySelector('.book-editor')));backdrop.dataset.path=pathKey;document.body.dataset.path=pathKey;document.body.classList.add('modal-open');document.getElementById('app').inert=true;dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-labelledby','formModalTitle');dialog.onkeydown=event=>{if(event.key==='Escape'){closeModal();return;}if(event.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(item=>!item.hidden&&item.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}};requestAnimationFrame(()=>dialog.querySelector('.modal-close,button,input,select,textarea')?.focus());if(location.search.includes('debugActions=1'))console.debug('[modal] opened',pathKey);};
  closeModal = function closeModalAndDrawer(id='formModal'){const host=document.getElementById(id);host?.classList.remove('dossier-drawer','experience-drawer','book-modal-backdrop');originalCloseModal(id);if(id==='formModal'){if(quickLink.secondDossierId){quickLink.firstDossierId='';quickLink.secondDossierId='';document.querySelectorAll('.is-link-source,.is-link-target').forEach(element=>element.classList.remove('is-link-source','is-link-target'));}document.body.classList.remove('modal-open');document.getElementById('app').inert=false;modalReturnFocus?.focus?.();if(location.search.includes('debugActions=1'))console.debug('[modal] closed');}};
  openEditCard = function(id){const appearance=appearanceById(id);if(appearance)openDossier(appearance.dossierId,id);else{const dossier=dossierById(id);if(dossier)openDossier(dossier.id);}};
  openLinkForm = function(prefill=''){startQuickLink(prefill);};
  openWallForm = function stableWallEditor(existing=null){const categories=(existing?.categories||activeWall().categories||[]).join(', ');modal(`<div class="wall-editor-dialog"><p class="eyebrow">Wall management</p><h2 id="formModalTitle">${existing?'Edit Wall':'Add Wall'}</h2><label>Wall name<input id="wName" value="${esc(existing?.name||'')}"></label><label>Description<textarea id="wDesc" rows="4">${esc(existing?.description||'')}</textarea></label><div class="friendly-grid"><label>Wall type<select id="wallType">${['book','series','investigation','custom'].map(type=>`<option value="${type}" ${existing?.wallType===type?'selected':''}>${type}</option>`).join('')}</select></label><label>Source series<select id="wallSourceSeries"><option value="">No source series</option>${state.series.map(item=>`<option value="${item.id}" ${existing?.sourceSeriesId===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><label>Source book<select id="wallSourceBook"><option value="">No source book</option>${bookOptions(existing?.sourceBookId||'')}</select></label><label>Default zoom<input id="wallDefaultZoom" type="number" min="0.2" max="2.5" step="0.1" value="${existing?.defaultZoom||1}"></label></div><label>Card categories<textarea id="wCats" rows="3">${esc(categories)}</textarea></label><div class="experience-footer"><button type="button" class="primary-button" id="saveWallStable">Save Wall</button><button type="button" class="secondary-button" id="cancelWallStable">Cancel</button>${existing&&state.walls.length>1?'<button type="button" class="danger-button" id="deleteWallStable">Delete Wall</button>':''}</div></div>`);document.getElementById('saveWallStable').onclick=()=>{const name=v('wName');if(!name)return showToast('Add a wall name.');const sourceBookId=v('wallSourceBook'),data={name,description:v('wDesc'),categories:v('wCats').split(',').map(value=>value.trim()).filter(Boolean),wallType:v('wallType'),sourceBookId,sourceSeriesId:v('wallSourceSeries')||state.books.find(book=>book.id===sourceBookId)?.seriesId||'',defaultZoom:Number(v('wallDefaultZoom'))||1};let wall=existing;if(wall)Object.assign(wall,data);else{wall={id:uid(),...data,cardView:validCardView()};state.walls.push(wall);state.activeWallId=wall.id;}state.wallViewports[wall.id]||={panX:0,panY:0,zoom:wall.defaultZoom};saveState();closeModal();renderWall();showToast(existing?'Wall updated.':'Wall added.');};document.getElementById('cancelWallStable').onclick=()=>closeModal();const remove=document.getElementById('deleteWallStable');if(remove)remove.onclick=()=>{if(!confirm(`Delete ${existing.name}? Dossier records will remain, but placements and regions on this wall will be removed.`))return;state.walls=state.walls.filter(wall=>wall.id!==existing.id);state.wallRegions=state.wallRegions.filter(region=>region.wallId!==existing.id);state.wallAppearances=state.wallAppearances.filter(appearance=>appearance.wallId!==existing.id);delete state.wallViewports[existing.id];state.activeWallId=state.walls[0].id;saveState();closeModal();renderWall();};};
  handleAction = function(a,id){if(a==='switch-wall'){quickLink.active=false;quickLink.firstDossierId='';quickLink.secondDossierId='';selectedAppearanceIds.clear();resetGestureState(document.getElementById('infiniteCanvas'));}if(a==='add-wall-card')return openDossierEditor();if(a==='create-link')return openLinkForm(id);return originalHandleAction(a,id);};

  openPinSource = function pinCanonicalSource(type,id){const source=sourceData(type,id);if(!source)return;modal(`<p class="eyebrow">Pin canonical dossier</p><h2 id="formModalTitle">Choose a wall</h2><p><strong>${esc(source.title)}</strong><br>${esc(source.text)}</p><label>Destination wall<select id="pinWall">${state.walls.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label>Category<input id="pinCategory" class="text-input" value="${esc(source.category)}"></label><button class="primary-button full-width" id="doPin">Pin to Wall</button>`);document.getElementById('doPin').onclick=()=>{let dossier=state.dossiers.find(d=>d.sourceType===type&&d.sourceId===id);if(!dossier){dossier={id:uid(),category:v('pinCategory')||source.category,title:source.title,summary:source.text,image:'',tags:[],sourceBookId:type==='book'?id:'',spoilerThreshold:'',fields:[],sections:[],tileSettings:defaultTileSettings(),sourceType:type,sourceId:id,createdAt:Date.now(),updatedAt:Date.now()};state.dossiers.push(dossier);}const wallId=v('pinWall');const existing=appearanceOnWall(dossier.id,wallId);if(!existing)createAppearanceOnWall(dossier.id,wallId,{values:{x:80,y:100,width:300,height:null,displayMode:'standard',zIndex:10,locked:false}});state.activeWallId=wallId;normalizeSeriesAndIntegrity();saveState();closeModal();switchView('wall');if(existing)requestAnimationFrame(()=>{selectedAppearanceIds.clear();selectedAppearanceIds.add(existing.id);focusAppearance(existing.id);showToast('This dossier is already on this wall.');});};};

  globalThis.InfiniteWall={openDossier,jumpToAppearance,moveHomeRegion,addRegionReference,assignMatchingDossier,appearanceWorld,setAppearanceRegion,resolvedCardView,validCardView,selectedAppearanceIds,DEFAULT_CARD_VIEW,renderWall,normalizeSeriesAndIntegrity,duplicateAppearanceGroups,appearanceOnWall,createAppearanceOnWall,clampWallScale,calculatePinchScale,calculateAnchoredViewport,calculateFitBounds,calculateFitViewport,screenDeltaToWorldDelta,sanitizeViewport,resetGestureState,fitAll,resetView,reevaluateRegions:()=>{runAutomaticAssignments();normalizeSeriesAndIntegrity();saveState();if(activeView==='wall')renderWall();}};

  migrateInvestigationState();
